package io.knowledgebrain.content;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.*;
import org.springframework.web.server.ResponseStatusException;
import jakarta.servlet.http.HttpServletRequest;
import tools.jackson.databind.json.JsonMapper;

@RestController
@ConditionalOnProperty(name="brain.content.snapshot.enabled",havingValue="true")
final class BrainSnapshotController {
 record Item(UUID entityId,UUID spaceId,long version,String payload){}
 record Page(UUID through,UUID nextAfter,List<Item> items){}
 private final JdbcTemplate jdbc;private final byte[] key;private final JsonMapper json=JsonMapper.builder().build();
 BrainSnapshotController(DataSource source,@Value("${brain.content.snapshot.key}")String key){if(!key.matches("[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("Scoped snapshot credential required");jdbc=new JdbcTemplate(source);this.key=("Bearer "+key).getBytes(StandardCharsets.US_ASCII);}
 private UUID id(String raw){if(raw==null)return null;var id=UUID.fromString(raw);if(id.version()!=7||id.variant()!=2||!id.toString().equals(raw))throw new IllegalArgumentException();return id;}
 @GetMapping("/internal/content/brain-snapshots") ResponseEntity<Page> read(HttpServletRequest request){
  if(!request.isSecure()||request.getContentLengthLong()>0||request.getHeader("Transfer-Encoding")!=null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"HTTPS required");var auth=Collections.list(request.getHeaders("Authorization"));if(auth.size()!=1||!MessageDigest.isEqual(key,auth.getFirst().getBytes(StandardCharsets.UTF_8)))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Snapshot credential required");if(request.getHeader("Cookie")!=null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Service credential only");
  try{for(var e:request.getParameterMap().entrySet())if(!Set.of("kind","limit","after","through").contains(e.getKey())||e.getValue().length!=1)throw new IllegalArgumentException();String kind=request.getParameter("kind");if(kind==null||!Set.of("NOTE","LINKS","NOTE_CONCEPTS","BOOKMARK","QUESTION","DECISION","BOOKMARK_CONCEPTS","QUESTION_CONCEPTS","DECISION_CONCEPTS").contains(kind))throw new IllegalArgumentException();UUID after=id(request.getParameter("after")),through=id(request.getParameter("through"));String raw=request.getParameter("limit");if(raw!=null&&!raw.matches("[1-5]"))throw new IllegalArgumentException();int limit=raw==null?5:Integer.parseInt(raw);if(after!=null&&(through==null||after.toString().compareTo(through.toString())>=0))throw new IllegalArgumentException();if(Set.of("BOOKMARK","QUESTION","DECISION","BOOKMARK_CONCEPTS","QUESTION_CONCEPTS","DECISION_CONCEPTS").contains(kind))return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(ContentRecordSnapshots.page(jdbc,json,kind,after,through,limit));String version=kind.equals("NOTE")?"version":kind.equals("LINKS")?"link_version":"concept_link_version",table=kind.equals("NOTE")?"note_revision":kind.equals("LINKS")?"note_link_revision":"note_concept_link_revision",ref=kind.equals("LINKS")?"source_note_id":"note_id",rv=kind.equals("NOTE_CONCEPTS")?"concept_link_version":version;
   if(through==null){var ids=jdbc.query("SELECT note_id FROM note WHERE "+version+">0 ORDER BY note_id DESC LIMIT 1",(rs,n)->rs.getObject(1,UUID.class));if(ids.isEmpty())return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new Page(null,null,List.of()));through=ids.getFirst();}
   String content=kind.equals("NOTE")?"r.title,r.markdown":kind.equals("LINKS")?"r.payload,n.links_dirty":"r.snapshot::text,n.version";
   String sql="SELECT n.note_id,n.space_id,r.revision_id,n."+version+",n.state,r.actor_id,r.occurred_at,"+content+" FROM note n LEFT JOIN "+table+" r ON r."+ref+"=n.note_id AND r."+rv+"=n."+version+" WHERE n."+version+">0 AND n.note_id<=?"+(after==null?"":" AND n.note_id>?")+" ORDER BY n.note_id LIMIT ?";
   var items=jdbc.query(sql,(rs,i)->{UUID entity=rs.getObject(1,UUID.class),space=rs.getObject(2,UUID.class),revision=rs.getObject(3,UUID.class);if(revision==null)throw new IllegalStateException("Canonical snapshot missing");long v=rs.getLong(4),time=rs.getTimestamp(7).toInstant().toEpochMilli();String state=rs.getString(5),actor=rs.getString(6);byte[] wire;
    if(kind.equals("NOTE")){var p=io.knowledgebrain.contracts.content.v1.NoteChangedPayloadV1.newBuilder().setNoteId(entity.toString()).setRevisionId(revision.toString()).setVersion(v).setState(state).setVisibility("PRIVATE").setTitle(rs.getString(8)).setMarkdown(rs.getString(9)).build();wire=io.knowledgebrain.contracts.content.v1.EventEnvelopeV1.newBuilder().setEventId(revision.toString()).setProducer("content-service").setAggregateType("Note").setAggregateId(entity.toString()).setSpaceId(space.toString()).setActorId(actor).setOccurredAtEpochMillis(time).setTraceId("e".repeat(32)).setEventVersion(1).setEventType(state.equals("RETIRED")?"NoteRetired":v==1?"NoteCreated":"NoteUpdated").setPayload(p.toByteString()).build().toByteArray();}
    else if(kind.equals("LINKS")){if(rs.getBoolean(9))throw new IllegalStateException("Canonical links are not resolved yet");wire=io.knowledgebrain.contracts.content.links.v1.LinkEventEnvelopeV1.newBuilder().setEventId(revision.toString()).setProducer("content-service").setAggregateType("NoteLinks").setAggregateId(entity.toString()).setSpaceId(space.toString()).setActorId(actor).setOccurredAtEpochMillis(time).setTraceId("e".repeat(32)).setEventVersion(1).setEventType("NoteLinksChanged").setPayload(com.google.protobuf.ByteString.copyFrom(rs.getBytes(8))).build().toByteArray();}
    else{var p=io.knowledgebrain.contracts.content.concepts.v1.NoteConceptsChangedPayloadV1.newBuilder().setNoteId(entity.toString()).setRevisionId(revision.toString()).setConceptVersion(v).setNoteVersion(rs.getLong(9)).setNoteState(state);var snapshot=json.readTree(rs.getString(8));for(var r:snapshot.path("items"))p.addLinks(io.knowledgebrain.contracts.content.concepts.v1.NoteConceptLinkV1.newBuilder().setLinkId(r.path("linkId").asString()).setConceptId(r.path("conceptId").asString()));wire=io.knowledgebrain.contracts.content.concepts.v1.ConceptEventEnvelopeV1.newBuilder().setEventId(revision.toString()).setProducer("content-service").setAggregateType("NoteConceptLinks").setAggregateId(entity.toString()).setSpaceId(space.toString()).setActorId(actor).setOccurredAtEpochMillis(time).setTraceId("e".repeat(32)).setEventVersion(1).setEventType("NoteConceptsChanged").setPayload(p.build().toByteString()).build().toByteArray();}return new Item(entity,space,v,Base64.getEncoder().encodeToString(wire));},after==null?new Object[]{through,limit+1}:new Object[]{through,after,limit+1});boolean more=items.size()>limit;var rows=List.copyOf(items.subList(0,Math.min(limit,items.size())));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new Page(through,more?rows.getLast().entityId():null,rows));
  }catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid snapshot request");}
 }
}
